  describe("Order Fill Queue", function () {
    it("Should fill orders in FIFO order at same price", async function () {
      const { crystal, market, maker, taker, quote } = await loadFixture(deployFixture);
      const scaleFactor = await market.scaleFactor();
      const quoteDecimals = await quote.decimals();
      const priceFactor = scaleFactor / (10n ** (18n - quoteDecimals));
      const priceParam = 500n * priceFactor;
      const size1 = ethers.parseEther("5");
      const size2 = ethers.parseEther("10");

      await crystal.connect(maker).limitOrder(market.target, false, 1, priceParam, size1, maker.address);
      await crystal.connect(maker).limitOrder(market.target, false, 1, priceParam, size2, maker.address);

      const levelBefore = await crystal.getPriceLevel(market.target, priceParam);
      expect(levelBefore.size).to.equal(size1 + size2);

      const fillSize = ethers.parseEther("3");
      await crystal.connect(taker).marketOrder(
        market.target, true, true, 0, ORDER_TYPES.NORMAL, fillSize, priceParam + 1n, ethers.ZeroAddress, taker.address
      );

      const levelAfter = await crystal.getPriceLevel(market.target, priceParam);
      expect(levelAfter.size).to.be.lessThan(levelBefore.size);
    });

    it("Should consume full first order before second", async function () {
      const { crystal, market, maker, taker, quote } = await loadFixture(deployFixture);
      const scaleFactor = await market.scaleFactor();
      const quoteDecimals = await quote.decimals();
      const priceFactor = scaleFactor / (10n ** (18n - quoteDecimals));
      const priceParam = 500n * priceFactor;
      const size1 = ethers.parseEther("2");
      const size2 = ethers.parseEther("10");

      await crystal.connect(maker).limitOrder(market.target, false, 1, priceParam, size1, maker.address);
      await crystal.connect(maker).limitOrder(market.target, false, 1, priceParam, size2, maker.address);

      const fillSize = ethers.parseEther("5");
      await crystal.connect(taker).marketOrder(
        market.target, true, true, 0, ORDER_TYPES.NORMAL, fillSize, priceParam + 1n, ethers.ZeroAddress, taker.address
      );

      const order1 = await crystal.getOrder(market.target, priceParam, 1n);
      expect(order1.size).to.equal(0n);
    });
  });

