  describe("Permit Edge Cases", function () {
    it("Should handle permit with valid signature", async function () {
      const { crystal, market, maker, taker } = await loadFixture(deployFixture);
      const amountQuote = ethers.parseUnits("10000", 6);
      const amountBase = ethers.parseEther("10");

      await crystal.connect(maker).addLiquidity(
        market.target,
        maker.address,
        amountQuote,
        amountBase,
        0,
        0
      );

      const value = ethers.parseEther("100");
      const block = await ethers.provider.getBlock("latest");
      const deadline = block.timestamp + 3600;
      const nonce = await market.nonces(maker.address);

      const domain = {
        name: await market.name(),
        version: "1",
        chainId: (await ethers.provider.getNetwork()).chainId,
        verifyingContract: market.target
      };

      const types = {
        Permit: [
          { name: "owner", type: "address" },
          { name: "spender", type: "address" },
          { name: "value", type: "uint256" },
          { name: "nonce", type: "uint256" },
          { name: "deadline", type: "uint256" }
        ]
      };

      const message = {
        owner: maker.address,
        spender: taker.address,
        value: value,
        nonce: nonce,
        deadline: deadline
      };

      const signature = await maker.signTypedData(domain, types, message);
      const { v, r, s } = ethers.Signature.from(signature);

      await market.permit(maker.address, taker.address, value, deadline, v, r, s);
      expect(await market.allowance(maker.address, taker.address)).to.equal(value);
    });
  });

