    it("Should add liquidity with ETH and refund excess (tests line 200 else + refund path)", async function () {
      const { crystal, market, maker } = await loadFixture(deployFixture);

      await crystal.connect(maker).addLiquidity(
        market.target,
        maker.address,
        ethers.parseUnits("1000", 6),
        ethers.parseEther("1"),
        0,
        0,
        { value: ethers.parseEther("1") }
      );

      const balanceBefore = await ethers.provider.getBalance(maker.address);

      const tx = await crystal.connect(maker).addLiquidity(
        market.target,
        maker.address,
        ethers.parseUnits("1000", 6),
        ethers.parseEther("2"),
        0,
        0,
        { value: ethers.parseEther("2") }
      );

      const receipt = await tx.wait();
      const gasUsed = receipt.gasUsed * receipt.gasPrice;
      const balanceAfter = await ethers.provider.getBalance(maker.address);

      expect(balanceAfter).to.be.greaterThan(balanceBefore - ethers.parseEther("2") - gasUsed);
    });

