      it("Should exercise cancel all orders", async function () {
        const { crystal, market, maker } = await loadFixture(deployFixture);

        await crystal.connect(maker).addLiquidity(
          market.target, maker.address, ethers.parseUnits("10000", 6), ethers.parseEther("10"), 0, 0
        );

        const scaleFactor = await market.scaleFactor();
        const tickSize = await market.tickSize();

        const orderIds = [];
        const basePrice = 1000n * scaleFactor / (10n ** 12n);
        const alignedBase = tickSize > 0n ? (basePrice / tickSize) * tickSize : basePrice;

        for (let i = 0; i < 3; i++) {
          const price = alignedBase + (BigInt(i) * tickSize);
          try {
            const tx = await crystal.connect(maker).limitOrder(
              market.target, true, 0, price, ethers.parseEther("0.1"), maker.address
            );
            const receipt = await tx.wait();
            const orderEvent = receipt.logs.find(log => {
              try { return crystal.interface.parseLog(log)?.name === "OrderCreated"; } catch { return false; }
            });
            if (orderEvent) {
              orderIds.push({
                price: price,
                id: crystal.interface.parseLog(orderEvent).args.id
              });
            }
          } catch (e) {

          }
        }

        for (const order of orderIds) {
          try {
            await crystal.connect(maker).cancelOrder(
              market.target, 0, order.price, order.id, maker.address
            );
          } catch (e) {

          }
        }
      });

