    describe("MarketType 1 (geometric) price functions", function () {
      async function deployGeometricMarket() {
        const [owner, maker, taker] = await ethers.getSigners();
        const TestToken = await ethers.getContractFactory("TestToken");
        const quote = await TestToken.deploy("Quote", "QUOTE", 6);
        const base = await TestToken.deploy("Base", "BASE", 18);

        const WETH = await ethers.getContractFactory("WETH");
        const weth = await WETH.deploy();

        const Crystal = await ethers.getContractFactory("Crystal");
        const crystal = await Crystal.deploy(
          weth.target, owner.address, owner.address, 10, 86400, LAUNCHPAD_PARAMS
        );

        await quote.mint(owner.address, ethers.parseUnits("100000000", 6));
        await base.mint(owner.address, ethers.parseEther("100000000"));
        await quote.mint(maker.address, ethers.parseUnits("100000000", 6));
        await base.mint(maker.address, ethers.parseEther("100000000"));
        await quote.mint(taker.address, ethers.parseUnits("100000000", 6));
        await base.mint(taker.address, ethers.parseEther("100000000"));

        await quote.approve(crystal.target, MAX_UINT256);
        await base.approve(crystal.target, MAX_UINT256);
        await quote.connect(maker).approve(crystal.target, MAX_UINT256);
        await base.connect(maker).approve(crystal.target, MAX_UINT256);
        await quote.connect(taker).approve(crystal.target, MAX_UINT256);
        await base.connect(taker).approve(crystal.target, MAX_UINT256);

        await crystal.connect(maker).registerUser(maker.address);
        await crystal.connect(taker).registerUser(taker.address);

        const depositQuote = ethers.parseUnits("50000000", 6);
        const depositBase = ethers.parseEther("50000000");
        await crystal.connect(maker).deposit(quote.target, depositQuote);
        await crystal.connect(maker).deposit(base.target, depositBase);
        await crystal.connect(taker).deposit(quote.target, depositQuote);
        await crystal.connect(taker).deposit(base.target, depositBase);

        const marketAddr = await crystal.deploy.staticCall(
          false, quote.target, base.target, 1, 21, 1, 1_000_000_000_000_000, 1_000_000, 99500, 99990
        );
        await crystal.deploy(
          false, quote.target, base.target, 1, 21, 1, 1_000_000_000_000_000, 1_000_000, 99500, 99990
        );
        const market = await ethers.getContractAt("CrystalMarket", marketAddr);

        await crystal.changeMarketParams(market.target, 1, 99970, 99990, true, false);

        await crystal.addLiquidity(
          market.target, owner.address, ethers.parseUnits("100000", 6), ethers.parseEther("100"), 0, 0
        );

        return { crystal, market, quote, base, owner, maker, taker };
      }

      it("Should hit _toValidPrice branches in geometric market", async function () {
        const { crystal, market, taker } = await deployGeometricMarket();

        await crystal.connect(taker).marketOrder(
          market.target, true, true, 0, 0, ethers.parseUnits("5000", 6), 0, ethers.ZeroAddress, taker.address
        );

        await crystal.connect(taker).marketOrder(
          market.target, false, true, 0, 0, ethers.parseEther("5"), 0, ethers.ZeroAddress, taker.address
        );
      });

      it("Should hit getPrice in geometric market", async function () {
        const { crystal, market } = await deployGeometricMarket();
        const result = await crystal.getPrice.staticCall(market.target);
        expect(result[0]).to.be.gt(0);
      });

      it("Should hit getQuote in geometric market", async function () {
        const { crystal, market } = await deployGeometricMarket();
        const result = await crystal.getQuote.staticCall(market.target, true, true, false, ethers.parseUnits("1000", 6), 0);
        expect(result[1]).to.be.gt(0);
      });
    });

