    describe("Lines 1541-1547 - transfer failure catch block", function () {
      it("Should handle transfer failure and credit internal balance", async function () {
        const [owner, maker, taker] = await ethers.getSigners();

        const WETH = await ethers.getContractFactory("WETH");
        const weth = await WETH.deploy();

        const FailingToken = await ethers.getContractFactory("FailingToken");
        const failToken = await FailingToken.deploy("Failing", "FAIL");

        const Crystal = await ethers.getContractFactory("Crystal");
        const crystal = await Crystal.deploy(
          weth.target, owner.address, owner.address, 10, 86400,
          [1000000000000000000000n, 99000, 5, 1000000000000000000n, 99920, 99990, 40]
        );

        await failToken.mint(owner.address, ethers.parseEther("1000000"));
        await failToken.mint(maker.address, ethers.parseEther("1000000"));
        await failToken.mint(taker.address, ethers.parseEther("1000000"));
        await weth.connect(owner).deposit({ value: ethers.parseEther("1000") });
        await weth.connect(maker).deposit({ value: ethers.parseEther("1000") });
        await weth.connect(taker).deposit({ value: ethers.parseEther("1000") });

        await failToken.connect(owner).approve(crystal.target, MAX_UINT256);
        await failToken.connect(maker).approve(crystal.target, MAX_UINT256);
        await failToken.connect(taker).approve(crystal.target, MAX_UINT256);
        await weth.connect(owner).approve(crystal.target, MAX_UINT256);
        await weth.connect(maker).approve(crystal.target, MAX_UINT256);
        await weth.connect(taker).approve(crystal.target, MAX_UINT256);

        const marketAddr = await crystal.deploy.staticCall(
          true, failToken.target, weth.target, 2, 15, 1, 1_000_000_000_000_000, 1_000_000, 99970, 99990
        );
        await crystal.deploy(true, failToken.target, weth.target, 2, 15, 1, 1_000_000_000_000_000, 1_000_000, 99970, 99990);

        await crystal.addLiquidity(marketAddr, owner.address, ethers.parseEther("1"), ethers.parseEther("10"), 0, 0);

        await crystal.connect(maker).registerUser(maker.address);
        await crystal.addressToUserId(maker.address);

        const bidPrice = 10n ** 13n;

        await crystal.connect(maker).limitOrder(marketAddr, true, 0, bidPrice, ethers.parseEther("10"), maker.address);

        await failToken.setRevertTransferTo(maker.address, true);

        await crystal.connect(taker).registerUser(taker.address);
        await crystal.connect(taker).marketOrder(marketAddr, false, true, 0, 0, ethers.parseEther("5"), 0, ethers.ZeroAddress, taker.address);
      });
    });

